{
  "variables": {
    "ANA": [1, 2, 3],
    "BRUNO": [1, 2, 3],
    "CARLA": [1, 2, 3],
    "DIEGO": [1, 2, 3]
  },
  "constraints": [
    {"id": "R1", "expr": "sum(ANA, BRUNO, CARLA, DIEGO) >= 4"},
    {"id": "R2", "expr": "not(and(ANA == BRUNO))"},
    {"id": "R3", "expr": "CARLA != 3"},
    {"id": "R4", "expr": "implies(CARLA == DIEGO, DIEGO == 1)"},
    {"id": "R5", "expr": "BRUNO != 1"},
    {"id": "R6", "expr": "not(ANA == 3)"},
    {"id": "R7", "expr": "not(DIEGO == 2)"}
  ]
}
